  const GR=/\b(?:grounds?|ground\s+(?:of|for)|gives\s+(?:a|the|its)\s+ground|adds\s+(?:a|the)\s+ground|rests?|resting|ties|because|on\s+that)\b/i,CAUSE=/\b(?:coming|overshadowing|overshadow|come\s+upon|begetting|begotten|conception|Holy\s+(?:Ghost|Spirit)|Spirit'?s|no\s+human\s+(?:biological\s+)?father)\b/i;
